import numpy as np
import json

with open('/tmp/demo_grid.json', 'r') as f:
    data = json.load(f)

in1 = np.array(data['demo1_in'])
out1 = np.array(data['demo1_out'])

# Build a lookup of all filled cells with their positions and values
filled = []
for r in range(23):
    for c in range(23):
        if in1[r,c] == 0:
            filled.append((r,c))

# For each diagonal d, find the pattern of values along that diagonal
from collections import defaultdict
by_diag = defaultdict(list)
for r,c in filled:
    d = c - r
    by_diag[d].append((r,c,out1[r,c]))

# Find the pattern for each diagonal
base = [1, 2, 3, 4, 5, 6]

print("Diagonal patterns:")
for d in sorted(by_diag.keys()):
    cells = sorted(by_diag[d], key=lambda x: x[0][0])
    vals = [v for (_,_,v) in cells]

    predicted = []
    for r,c,val in cells:
        found = False
        for off in range(6):
            if base[(r + off) % 6] == val:
                predicted.append(off)
                found = True
                break
        if not found:
            predicted.append(None)

    if all(p is not None for p in predicted):
        if len(set(predicted)) == 1:
            offset = predicted[0]
            pattern = base[offset:offset+6]
            print(f"  d={d:2d}: offset={offset}, pattern={pattern}, cells={len(cells)}")
        else:
            print(f"  d={d:2d}: offsets={predicted}, cells={len(cells)}")
    else:
        print(f"  d={d:2d}: inconsistent, cells={len(cells)}")

