import numpy as np
import json

with open('/tmp/demo_grid.json', 'r') as f:
    data = json.load(f)

in1 = np.array(data['demo1_in'])
out1 = np.array(data['demo1_out'])

base = [1, 2, 3, 4, 5, 6]

def predict_v5(r, c):
    if r <= c:
        return base[(c + 4) % 6]
    else:
        return base[(c + 5) % 6]

matches = 0
mismatches = []
for r in range(23):
    for c in range(23):
        if out1[r,c] != 0:
            if predict_v5(r,c) == out1[r,c]:
                matches += 1
            else:
                mismatches.append((r,c, predict_v5(r,c), out1[r,c]))

print(f"Matches: {matches}/529")

# Check for any remaining mismatches in r > c region
print("\nMismatches in r > c region:")
for r,c,pred,actual in mismatches:
    if r > c:
        print(f"  ({r},{c}): pred={pred}, actual={actual}")

# Check for any remaining mismatches in r <= c region
print("\nMismatches in r <= c region:")
for r,c,pred,actual in mismatches:
    if r <= c:
        print(f"  ({r},{c}): pred={pred}, actual={actual}")

if len(mismatches) == 0:
    print("\nAll cells match!")

